       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_14_v1'
from (values
('127.98.d.28',3,'Which source gives a student reliable information on the schooling and training needed for a construction career?','["The Occupational Outlook Handbook", "A product advertisement", "A random chat room", "A rumor"]'::jsonb,0,'Government career guides list training, pay, and outlook.','original'),
('127.98.d.28',4,'A student interested in being a general contractor should investigate the career''s:','["Favorite colors", "Education, licensing, and experience requirements", "Parking rules", "Weather forecast"]'::jsonb,1,'Entry requirements shape a career plan.','original'),
('127.98.d.1.A',3,'A carpenter explains a delay to a homeowner. The best approach is to:','["Avoid the owner", "Use only jargon", "Speak clearly, give the reason, and follow up in writing", "Say nothing"]'::jsonb,2,'Verbal and written communication work together.','original'),
('127.98.d.1.A',4,'Following a phone call about a change in scope, the carpenter should send:','["A map to the site", "A joke", "Nothing at all", "A written confirmation of what was agreed"]'::jsonb,3,'Written confirmation prevents later disputes.','original'),
('127.98.d.1.B',3,'A work order for a framing crew should include:','["The task, location, materials, and due date", "Only the weather", "Only the date", "Only the foreman''s name"]'::jsonb,0,'Work orders direct tasks.','original'),
('127.98.d.1.B',4,'Filing completed work orders in the project folder helps to:','["Lose records", "Prove what work was done and when", "Delay billing", "Hide work"]'::jsonb,1,'Paperwork supports billing and disputes.','original'),
('127.98.d.1.C',3,'Estimating a remodel includes finding the cost of materials, labor, and:','["Last year''s weather", "The owner''s taste in music", "Overhead and profit", "Nothing else"]'::jsonb,2,'Complete estimates cover all costs.','original'),
('127.98.d.1.C',4,'Legal restrictions such as setback rules must be considered in an estimate because they can:','["Cancel the weather", "Reduce all costs", "Raise the sun", "Change the size or location of what can be built"]'::jsonb,3,'Rules affect scope and cost.','original'),
('127.98.d.1.D',3,'A schematic of a stair layout helps a carpenter to:','["Understand dimensions and parts before building", "Skip the plans", "Avoid measuring", "Paint the stairs"]'::jsonb,0,'Drawings guide the work.','original'),
('127.98.d.1.D',4,'A blueprint note reading ''verify in field'' means the builder should:','["Skip the step", "Check the measurement on site before cutting", "Ignore it", "Guess"]'::jsonb,1,'Field verification prevents errors.','original'),
('127.98.d.1.E',3,'Descriptive geometry helps builders solve problems involving true lengths and angles of:','["Parking lots", "Door colors", "Inclined or intersecting surfaces such as roofs", "Wall paint"]'::jsonb,2,'It is used for hips, valleys, and complex joints.','original'),
('127.98.d.1.E',4,'An auxiliary view is drawn to show a surface that is:','["Painted", "Always flat to the viewer", "Missing from the plan", "Slanted so its true size does not appear in normal views"]'::jsonb,3,'Auxiliary views reveal true shape.','original'),
('127.98.d.2.A',3,'Which pair is a common construction material?','["Concrete and lumber", "Glass jars and balloons", "Chalk and ribbon", "Rubber bands and paper"]'::jsonb,0,'Concrete and lumber are staples.','original'),
('127.98.d.2.A',4,'Light-frame construction in houses is mostly built from:','["Poured steel", "Dimensional lumber and sheet goods", "Solid stone", "Bamboo only"]'::jsonb,1,'Wood framing dominates residential building.','original'),
('127.98.d.2.B',3,'Hardwoods come from:','["Cactus", "Pine trees", "Broadleaf deciduous trees such as oak", "Palm fronds"]'::jsonb,2,'Oak and maple are hardwoods.','original'),
('127.98.d.2.B',4,'Softwood lumber such as Douglas fir is widely used for:','["Fine furniture only", "Musical instruments only", "Jewelry boxes only", "Structural framing"]'::jsonb,3,'Softwoods are strong and economical.','original'),
('127.98.d.2.C',3,'The grade stamp on a piece of lumber tells the buyer about its:','["Quality and strength class", "Age of the tree", "Color", "Delivery driver"]'::jsonb,0,'Grades guide use.','original'),
('127.98.d.2.C',4,'Lumber stamped ''KD'' has been:','["Kicked back", "Kiln dried", "Kept damp", "Knocked down"]'::jsonb,1,'KD means reduced moisture content.','original'),
('127.98.d.2.D',3,'Lumber stored on a site should be kept:','["In direct mud", "Under open rain", "Off the ground and covered", "In a puddle"]'::jsonb,2,'Moisture warps wood.','original'),
('127.98.d.2.D',4,'Stacking lumber with stickers (spacers) between layers allows:','["Insects", "Trapped moisture", "Faster rot", "Air to circulate"]'::jsonb,3,'Airflow keeps wood dry.','original'),
('127.98.d.2.E',3,'A common engineered lumber product used for long spans is a:','["Laminated veneer lumber (LVL) beam", "Glass rod", "Plastic tube", "Rubber bar"]'::jsonb,0,'Engineered beams carry high loads.','original'),
('127.98.d.2.E',4,'Plywood and OSB are engineered panels often used as:','["Roof shingles only", "Sheathing and subflooring", "Window glass", "Wiring"]'::jsonb,1,'Panels cover large areas quickly.','original'),
('127.98.d.2.F',3,'A board foot is a unit of volume equal to:','["12 cubic inches", "1 cubic inch", "144 cubic inches", "1,000 cubic inches"]'::jsonb,2,'1 inch x 12 inches x 12 inches = 144.','original'),
('127.98.d.2.F',4,'How many board feet are in a 2 x 4 that is 8 feet long?','["8 board feet", "2 board feet", "16 board feet", "5.33 board feet"]'::jsonb,3,'(2 x 4 x 8) / 12 = 5.33.','original'),
('127.98.d.2.G',3,'Anchors are used to attach wood framing to a:','["Concrete foundation", "Glass window", "Cloud", "Paper sheet"]'::jsonb,0,'Anchor bolts tie sills to foundations.','original'),
('127.98.d.2.G',4,'Construction adhesives are often used with nails on subfloors to:','["Make it slippery", "Reduce squeaks and add stiffness", "Color the floor", "Add weight"]'::jsonb,1,'Glue plus fasteners improves the floor.','original'),
('127.98.d.3.A',3,'The universal systems model has inputs, processes, outputs, and:','["Lunch", "Furniture", "Feedback", "Tires"]'::jsonb,2,'Feedback adjusts the system.','original'),
('127.98.d.3.A',4,'Applying the systems model to building a shed, the plans and lumber are the:','["Outputs", "Feedback", "Breaks", "Inputs"]'::jsonb,3,'Resources entering the system are inputs.','original'),
('127.98.d.3.B',3,'In a building project, the finished structure is an:','["Output", "Resource", "Input", "Process"]'::jsonb,0,'Outputs are the results.','original'),
('127.98.d.3.B',4,'An inspection report that leads the crew to change a step is:','["Output", "Feedback", "Input", "Process only"]'::jsonb,1,'Feedback prompts adjustment.','original'),
('127.98.d.3.C',3,'A subsystem of a house that carries water is the:','["Roof", "Stairs", "Plumbing system", "Door"]'::jsonb,2,'Plumbing is a subsystem.','original'),
('127.98.d.3.C',4,'The structural, electrical, and mechanical parts of a building are examples of:','["Hobbies", "Rumors", "Colors", "Subsystems"]'::jsonb,3,'Subsystems work together.','original'),
('127.98.d.3.D',3,'When framing, electrical, and plumbing crews coordinate, they show that systems:','["Interact to reach a common goal", "Work alone", "Compete with each other", "Never touch"]'::jsonb,0,'Coordination reaches the shared outcome.','original'),
('127.98.d.3.D',4,'If the plumber cuts a joist without approval, the structural system may be:','["Painted", "Weakened", "Strengthened", "Unchanged"]'::jsonb,1,'Systems affect one another.','original'),
('127.98.d.4.A',3,'Civil construction typically includes:','["Furniture", "Kitchens and bedrooms", "Roads, bridges, and dams", "Paint"]'::jsonb,2,'Civil projects serve the public.','original'),
('127.98.d.4.A',4,'Architectural construction is mainly about:','["Dams", "Highways", "Pipelines", "Buildings people occupy"]'::jsonb,3,'Architecture covers buildings.','original'),
('127.98.d.4.B',3,'A community that needs a safe crossing over a creek might apply construction technology by building a:','["Footbridge", "Flagpole", "Mural", "Fountain"]'::jsonb,0,'Construction can solve local problems.','original'),
('127.98.d.4.B',4,'Building a ramp for a person using a wheelchair applies construction technology to an:','["Film plot", "Individual need", "Business tax", "Weather forecast"]'::jsonb,1,'It addresses a personal need.','original'),
('127.98.d.4.C',3,'A factor that affects whether a family buys a house is its:','["Crew uniforms", "Brand of hammer", "Cost and location", "Color of nails"]'::jsonb,2,'Cost and location influence purchase.','original'),
('127.98.d.4.C',4,'Interest rates affect construction because they change:','["The length of boards", "The weather", "The size of nails", "How much buyers can afford to borrow"]'::jsonb,3,'Financing shapes demand.','original'),
('127.98.d.4.D',3,'One role of construction in society is to:','["Provide shelter and infrastructure", "Stop cities from growing", "Replace schools with farms", "Remove roads"]'::jsonb,0,'Construction meets needs.','original'),
('127.98.d.4.D',4,'The construction industry supports communities by creating:','["Weather", "Jobs and needed buildings", "Noise only", "Traffic only"]'::jsonb,1,'It employs people and serves needs.','original'),
('127.98.d.5.A',3,'A first step in the design process is to:','["Hang the doors", "Pour concrete", "Identify the need or problem", "Buy materials"]'::jsonb,2,'Design starts with a need.','original'),
('127.98.d.5.A',4,'Making a scale model before building is useful because it:','["Replaces the permit", "Cuts the lumber", "Pays the crew", "Lets designers test ideas cheaply"]'::jsonb,3,'Models reveal flaws early.','original'),
('127.98.d.5.B',3,'A student designs a doghouse to fit a 50-pound dog. The size requirement is a:','["Specified need", "Hobby", "Coincidence", "Rumor"]'::jsonb,0,'Specs come from user needs.','original'),
('127.98.d.5.B',4,'Improving a design after testing is called:','["Dismissal", "Iteration", "Delay", "Duplication"]'::jsonb,1,'Iterating improves the result.','original'),
('127.98.d.5.C',3,'Designing a stair with a handrail adds:','["Cost only", "Noise", "Safety", "Weight only"]'::jsonb,2,'Built-in safety reduces injuries.','original'),
('127.98.d.5.C',4,'Choosing a stronger bolt for a swing set improves:','["Color", "Humor", "Friendliness", "Reliability"]'::jsonb,3,'Stronger parts fail less often.','original'),
('127.98.d.6.A',3,'An emerging construction technology is:','["3D-printed buildings", "Candle lighting", "Horse-drawn wagons", "Hand-cranked drills"]'::jsonb,0,'Additive construction is new.','original'),
('127.98.d.6.A',4,'Reporting on a new building material should include its:','["Fan base", "Benefits, limits, and costs", "Zodiac sign", "Voice"]'::jsonb,1,'Reports should be balanced.','original'),
('127.98.d.6.B',3,'To test which beam resists bending more, a student would:','["Guess", "Ask a stranger", "Load identical spans and compare deflection", "Choose by color"]'::jsonb,2,'Experiments need fair comparisons.','original'),
('127.98.d.6.B',4,'Controlling variables in a materials test means:','["Ignoring results", "Changing everything", "Skipping tests", "Changing one factor at a time"]'::jsonb,3,'One variable gives clear results.','original'),
('127.98.d.7.A',3,'A quality-control check in framing is to:','["Verify that walls are plumb and square", "Skip measuring", "Remove the nails", "Paint the studs"]'::jsonb,0,'Checks catch errors.','original'),
('127.98.d.7.A',4,'Inspecting concrete slump before a pour is an example of:','["Hiring", "Quality control", "Scheduling", "Marketing"]'::jsonb,1,'Testing keeps quality in range.','original'),
('127.98.d.7.B',3,'Continuous improvement means the crew:','["Never changes", "Repeats errors", "Looks for ways to do each task better every time", "Avoids feedback"]'::jsonb,2,'Small gains add up.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
