insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_14_v1'
from (values
('127.103.d.2.D',3,'Good housekeeping on a masonry site includes:','["Stacking blocks in doors", "Ignoring spills", "Leaving tools in aisles", "Keeping debris and mortar droppings cleared from walkways"]'::jsonb,3,'Clear paths prevent trips.','original'),
('127.103.d.2.D',4,'Stacking block at the base of a ladder is a housekeeping:','["Violation", "Practice", "Strategy", "Habit"]'::jsonb,0,'Ladders need clear bases.','original'),
('127.103.d.2.E',3,'Wet mortar and concrete can burn skin because they are:','["Soft", "Caustic", "Cold", "Sweet"]'::jsonb,1,'Cement is highly alkaline.','original'),
('127.103.d.2.E',4,'If wet concrete gets on your skin, you should:','["Rub it with a rag", "Wait until it dries", "Wash it off promptly with clean water", "Cover it"]'::jsonb,2,'Prolonged contact causes burns.','original'),
('127.103.d.2.F',3,'Flammable liquids such as solvents should be stored in:','["Open pails", "Soda bottles", "Plastic grocery bags", "Approved safety containers"]'::jsonb,3,'Containers prevent fires.','original'),
('127.103.d.2.F',4,'Smoking near flammable liquids is:','["A fire hazard and not allowed", "Safe", "Encouraged", "Required"]'::jsonb,0,'Ignition sources are prohibited.','original'),
('127.103.d.3.A',3,'Protective lenses or face shields are worn to protect from:','["Odors", "Flying chips and splashes", "Cold air", "Noise"]'::jsonb,1,'Eye and face protection matter.','original'),
('127.103.d.3.A',4,'When grinding block, a face shield is worn in addition to:','["Earrings", "Sunglasses", "Safety glasses", "A cap"]'::jsonb,2,'Layered protection is best.','original'),
('127.103.d.3.B',3,'Earplugs or earmuffs are required when noise reaches:','["50 decibels", "30 decibels", "10 decibels", "85 decibels or more over time"]'::jsonb,3,'OSHA sets limits near 85-90 dBA.','original'),
('127.103.d.3.B',4,'Using a masonry saw without hearing protection can lead to:','["Permanent hearing loss", "More energy", "Louder voice", "Better hearing"]'::jsonb,0,'Noise damages hearing.','original'),
('127.103.d.3.C',3,'Gloves for masons should protect hands from:','["Nothing", "Abrasion and caustic mortar", "Sweat only", "Cold drinks"]'::jsonb,1,'Rubber and leather gloves help.','original'),
('127.103.d.3.C',4,'Wearing rubber gloves with long cuffs while handling wet mortar helps prevent:','["Sunburn", "Cold feet", "Chemical burns", "Thirst"]'::jsonb,2,'Cement burns skin.','original'),
('127.103.d.3.D',3,'A respirator is needed when cutting block to protect against:','["Noise", "Heat", "Cold", "Dust"]'::jsonb,3,'Respirators filter air.','original'),
('127.103.d.3.D',4,'A respirator must be:','["Properly fitted and rated for the hazard", "Loose", "Worn on the forehead", "Any style"]'::jsonb,0,'Fit testing is required.','original'),
('127.103.d.4.A',3,'Fall protection is required on masonry scaffolds above:','["Zero feet", "The OSHA trigger height", "The ground", "One inch"]'::jsonb,1,'Fall protection triggers at set heights.','original'),
('127.103.d.4.A',4,'Guardrails, safety nets, or personal fall arrest are all methods of:','["Rain protection", "Wind protection", "Fall protection", "Sun protection"]'::jsonb,2,'Several systems protect from falls.','original'),
('127.103.d.4.B',3,'A personal fall arrest system includes an anchor, a connector, and a:','["Rope only", "Hard hat only", "Belt only", "Full-body harness"]'::jsonb,3,'Harness spreads forces.','original'),
('127.103.d.4.B',4,'A harness must be inspected before each use for:','["Cuts, burns, and damage", "Color", "Price", "Brand"]'::jsonb,0,'Damaged gear may fail.','original'),
('127.103.d.4.C',3,'A safe scaffold must be erected on:','["Stacks of blocks", "Firm, level footing", "Loose bricks", "Soft mud"]'::jsonb,1,'Solid base prevents collapse.','original'),
('127.103.d.4.C',4,'Before use, a scaffold should be inspected by a:','["Passerby", "Neighbor", "Competent person", "New hire only"]'::jsonb,2,'Competent person inspects scaffolds.','original'),
('127.103.d.4.D',3,'Toeboards or debris nets on scaffolds protect people below from:','["Noise", "Rain", "Heat", "Falling objects"]'::jsonb,3,'Overhead protection saves lives.','original'),
('127.103.d.4.D',4,'Workers below an overhead masonry operation should:','["Be kept out of the drop zone or protected", "Stand directly under", "Ignore signs", "Work faster"]'::jsonb,0,'Drop zones are barricaded.','original'),
('127.103.d.5.A',3,'A hand tool with a damaged handle should be:','["Painted", "Repaired or replaced before use", "Sold", "Used"]'::jsonb,1,'Damaged tools cause injuries.','original'),
('127.103.d.5.A',4,'Chisels should be used with a mushroomed head:','["Only on brick", "Only outdoors", "Never; dress or replace the head", "Always"]'::jsonb,2,'Mushroomed heads chip.','original'),
('127.103.d.5.B',3,'A masonry saw is safest to use when it:','["Is unplugged", "Has no guard", "Is dry", "Has a wet-cutting dust control and a guard"]'::jsonb,3,'Wet cutting reduces dust.','original'),
('127.103.d.5.B',4,'Before using a masonry saw, you should confirm the blade is:','["Rated for masonry and free of cracks", "Dull", "Cracked", "Wooden"]'::jsonb,0,'Inspect the blade.','original'),
('127.103.d.5.C',3,'A mortar mixer''s moving paddles are dangerous because they can:','["Cool mortar", "Catch hands or tools", "Add water", "Cut sand"]'::jsonb,1,'Never reach into a running mixer.','original'),
('127.103.d.5.C',4,'Before cleaning a mortar mixer, you should:','["Leave it running", "Use a shovel while running", "Shut it off and lock out the power", "Reach in"]'::jsonb,2,'Lockout/tagout applies.','original'),
('127.103.d.5.D',3,'A handheld grinder with a missing guard should be:','["Used on masonry only", "Used carefully", "Used outdoors", "Taken out of service"]'::jsonb,3,'Guards prevent injuries.','original'),
('127.103.d.5.D',4,'Sparks from a grinder can ignite:','["Flammable materials nearby", "Water", "Sand", "Bricks"]'::jsonb,0,'Keep flammables away.','original'),
('127.103.d.5.E',3,'Powder-actuated tools use a:','["Magnet", "Powder-charged load to drive fasteners", "Water jet", "Air only"]'::jsonb,1,'They act like a firearm.','original'),
('127.103.d.5.E',4,'Only workers who have been trained and certified may use:','["Tape measures", "Hammers", "Powder-actuated tools", "Levels"]'::jsonb,2,'Training is required.','original'),
('127.103.d.5.F',3,'When working around a forklift, stay out of its:','["Rear mirror", "Spare tire", "Cab roof", "Path and never walk under raised forks"]'::jsonb,3,'Forklifts cause serious injuries.','original'),
('127.103.d.5.F',4,'A forklift operator must be:','["Trained and certified", "Distracted", "Anyone available", "Unlicensed"]'::jsonb,0,'Operator qualification is required.','original'),
('127.103.d.5.G',3,'A basic electrical safety guideline on a masonry site is to use:','["Wet extension cords", "Ground-fault circuit interrupters (GFCIs)", "Frayed cords", "Bare wires"]'::jsonb,1,'GFCIs protect from shock.','original'),
('127.103.d.5.G',4,'Power lines overhead require workers to:','["Ignore them", "Touch them", "Keep scaffolds and equipment at a safe distance", "Climb them"]'::jsonb,2,'Maintain clearance.','original'),
('127.103.d.5.H',3,'Masonry units should be stockpiled on:','["Stacked planks", "Slopes", "Soft mud", "Firm, level ground"]'::jsonb,3,'Stability prevents shifting.','original'),
('127.103.d.5.H',4,'Cement bags should be stored:','["Dry, off the ground, and covered", "On wet floors", "In rain", "In puddles"]'::jsonb,0,'Moisture hardens cement.','original'),
('127.103.d.5.I',3,'Bricks are stacked safely in cubes that are no more than:','["As high as possible", "A safe height set by the employer and manufacturer", "Unbalanced", "A single tall pile"]'::jsonb,1,'Stack height is limited.','original'),
('127.103.d.5.I',4,'Loose bricks on a pallet should be:','["Thrown", "Left loose", "Banded or strapped for stability", "Stacked unevenly"]'::jsonb,2,'Banding prevents spills.','original'),
('127.103.d.6.A',3,'A brick trowel is used to:','["Level", "Cut bricks", "Measure", "Pick up and spread mortar"]'::jsonb,3,'The trowel is the mason''s basic tool.','original'),
('127.103.d.6.A',4,'A pointing trowel is used to:','["Finish and repair joints", "Mix mortar", "Cut stones", "Drive nails"]'::jsonb,0,'Pointing refines joints.','original'),
('127.103.d.6.B',3,'A brick hammer has one flat face and a:','["Claw", "Chisel end", "Saw", "Bit"]'::jsonb,1,'It can strike and split bricks.','original'),
('127.103.d.6.B',4,'A brick set (wide chisel) is used to:','["Mix mortar", "Measure", "Cut bricks cleanly", "Spread mortar"]'::jsonb,2,'Sets split brick.','original'),
('127.103.d.6.C',4,'A soft brush is used to:','["Mix mortar", "Level a wall", "Cut brick", "Remove excess mortar and dust from the wall surface"]'::jsonb,3,'Brushing cleans up joints.','original'),
('127.103.d.6.D',3,'A tool commonly used to hold the line in place at a corner is a:','["Line block or pin", "Trowel", "Saw", "Wrench"]'::jsonb,0,'Line blocks hold strings.','original'),
('127.103.d.6.D',4,'A mason''s hawk is used to:','["Measure", "Hold a small supply of mortar", "Hammer", "Cut brick"]'::jsonb,1,'A hawk keeps mortar handy.','original'),
('127.103.d.7.A',3,'A modular spacing rule helps masons to:','["Mix grout", "Cut mortar", "Lay out courses and openings accurately", "Weigh bricks"]'::jsonb,2,'Rules give course heights.','original'),
('127.103.d.7.A',4,'On a standard modular spacing rule, three courses of brick with mortar joints measure:','["12 inches", "10 inches", "6 inches", "8 inches"]'::jsonb,3,'Standard modular brick runs 2 2/3 inches per course, so three courses total 8 inches.','original'),
('127.103.d.7.B',3,'A mason uses a level to check that a course is:','["Horizontal", "Vertical only", "Diagonal", "Painted"]'::jsonb,0,'Levels indicate horizontal and vertical alignment.','original'),
('127.103.d.7.B',4,'Placing a level on its end against a wall''s edge checks:','["Moisture", "Plumb", "Color", "Weight"]'::jsonb,1,'Vertical alignment.','original'),
('127.103.d.7.C',3,'A plumb bob is used to:','["Cut stone", "Mix mortar", "Find a true vertical line", "Measure weight"]'::jsonb,2,'Gravity gives vertical.','original'),
('127.103.d.7.C',4,'A laser level projects a:','["Smell", "Sound", "Heat", "Level or plumb reference line"]'::jsonb,3,'Lasers help alignment.','original'),
('127.103.d.7.D',3,'A corner pole is used to:','["Guide course heights at wall ends", "Hold lunch", "Cut stone", "Support roofs"]'::jsonb,0,'Poles set course marks.','original'),
('127.103.d.7.D',4,'A mason''s line stretched between corners helps keep courses:','["Wavy", "Straight and level", "Uneven", "Crooked"]'::jsonb,1,'The line guides each unit.','original')
